def roundline(lo, hi, val, w=1000, fmt=lambda v: str(int(v))):
    x0, x1 = 60, w - 60
    X = lambda v: x0 + (v - lo) / (hi - lo) * (x1 - x0)
    mid = (lo + hi) / 2
    tgt = lo if val < mid else hi
    y = 90
    b = line(x0 - 10, y, x1 + 10, y, NAVY, 5)
    for i in range(0, 11):
        v = lo + (hi - lo) * i / 10
        b += line(X(v), y - 10, X(v), y + 10, NAVY, 3)
    b += T(X(lo), y + 48, fmt(lo), 30, NAVY) + T(X(hi), y + 48, fmt(hi), 30, NAVY) + T(X(mid), y + 48, fmt(mid), 26, GREY)
    b += line(X(mid), 20, X(mid), y, GREY, 3, '8 8') + T(X(mid), 14, 'ពាក់កណ្តាល', 22, GREY)
    b += circ(X(val), y, 15, RED, '#fff', 3) + T(X(val), y - 26, fmt(val), 30, RED)
    b += f'<path d="M{X(val)} {y+60} Q{(X(val)+X(tgt))/2} {y+120} {X(tgt)} {y+60}" stroke="{GREEN}" stroke-width="5" fill="none"/>' + f'<polygon points="{X(tgt)},{y+60} {X(tgt)-10},{y+80} {X(tgt)+10},{y+78}" fill="{GREEN}"/>'
    return svg(w, 210, b, '28vh')


def rule_boxes():
    return fig(svg(1000, 170, rect(20, 14, 460, 140, BLUE, 24) + T(250, 70, '0  1  2  3  4', 44, '#fff') + T(250, 126, 'បង្កត់ចុះ ↓', 36, '#cfe6ff') + rect(520, 14, 460, 140, ORANGE, 24) + T(750, 70, '5  6  7  8  9', 44, '#fff') + T(750, 126, 'បង្កត់ឡើង ↑', 36, '#fff0cc'), '22vh'))


def sqgrid(n, cell=44):
    W = n * cell + 20
    b = ''.join(rect(10 + j * cell, 10 + i * cell, cell - 3, cell - 3, '#7fc4ff', 4) for i in range(n) for j in range(n))
    return W, b


